import { getActiveFormats } from '../../get-active-formats';
import { isCollapsed } from '../../is-collapsed';
import { updateFormats } from '../../update-formats';
import { ownsSelection } from '../../owns-selection';
import type { RichTextFormatList } from '../../types';
import type { RichTextField } from '../types';

/**
 * All inserting input types that would insert HTML into the DOM.
 *
 * @see https://www.w3.org/TR/input-events-2/#interface-InputEvent-Attributes
 */
const INSERTION_INPUT_TYPES_TO_IGNORE = new Set( [
	'insertParagraph',
	'insertOrderedList',
	'insertUnorderedList',
	'insertHorizontalRule',
	'insertLink',
] );

const EMPTY_ACTIVE_FORMATS: RichTextFormatList = [];

const PLACEHOLDER_ATTR_NAME = 'data-rich-text-placeholder';

// Listen for the release only during a press in this element, so fields
// don't each keep window listeners.
export function onPointerDown( field: RichTextField ) {
	const { defaultView } = field.element.ownerDocument;
	field.isPointerDown = true;

	function onPointerUp() {
		field.isPointerDown = false;
		defaultView!.removeEventListener( 'pointerup', onPointerUp );
		defaultView!.removeEventListener( 'pointercancel', onPointerUp );
	}

	defaultView!.addEventListener( 'pointerup', onPointerUp );
	defaultView!.addEventListener( 'pointercancel', onPointerUp );
}

export function onInput(
	field: RichTextField,
	event?: Event | Pick< InputEvent, 'inputType' >
) {
	// Do not trigger a change if characters are being composed. Browsers
	// will usually emit a final `input` event when the characters are
	// composed. As of December 2019, Safari doesn't support
	// nativeEvent.isComposing.
	if ( field.isComposing ) {
		return;
	}

	let inputType;

	if ( event && 'inputType' in event ) {
		inputType = event.inputType;
	}

	const { record, applyRecord, createRecord, handleChange } =
		field.props.current;

	// The browser formatted something or tried to insert HTML. Overwrite
	// it. It will be handled later by the format library if needed.
	if (
		inputType &&
		( inputType.indexOf( 'format' ) === 0 ||
			INSERTION_INPUT_TYPES_TO_IGNORE.has( inputType ) )
	) {
		applyRecord( record.current );
		return;
	}

	const currentValue = createRecord();
	const { start } = record.current;

	if ( start === undefined || currentValue.start === undefined ) {
		handleChange( currentValue );
		return;
	}

	// When a non-collapsed selection is deleted (not replaced with new
	// text), the old active formats refer to the deleted content and
	// should not be carried forward.
	const clearFormats =
		! isCollapsed( record.current ) && currentValue.start <= start;
	const oldActiveFormats = getActiveFormats(
		record.current,
		EMPTY_ACTIVE_FORMATS
	);

	// Update the formats between the last and new caret position.
	const change = updateFormats( {
		value: currentValue,
		start,
		end: currentValue.start,
		formats: clearFormats ? [] : oldActiveFormats,
	} );

	handleChange( change );
}

/**
 * Syncs the selection to local state. A callback for the `selectionchange`
 * event, and for the capture phase of events that consume the selection,
 * which run before `selectionchange` is delivered.
 *
 * @param field The field.
 */
export function handleSelectionChange( field: RichTextField ) {
	const { element } = field;
	const { ownerDocument } = element;
	const { defaultView } = ownerDocument;
	const { record, applyRecord, createRecord, onSelectionChange } =
		field.props.current;

	// Check if the implementor disabled editing. `contentEditable` does
	// disable input, but not text selection, so we must ignore selection
	// changes.
	if ( element.contentEditable !== 'true' ) {
		return;
	}

	// Ensure the active element is the rich text element, or that the
	// element owns the selection through a focused editing host (the
	// editable block editor canvas wrapper). The listener stays
	// subscribed but no-ops for instances that don't own the selection.
	if (
		ownerDocument.activeElement !== element &&
		! ownsSelection( element )
	) {
		return;
	}

	// In case of a keyboard event, ignore selection changes during
	// composition.
	if ( field.isComposing ) {
		return;
	}

	const selection = defaultView!.getSelection()!;

	// Skip selections that have already been processed into the current
	// record, such as the `selectionchange` event for a selection that
	// was synchronized on capture of a consuming event, or coalesced
	// duplicates. The offsets the processing produced are compared to
	// the record too: the record's selection may be rewritten from
	// (possibly stale) props on render without the DOM selection moving,
	// in which case the selection must be processed again.
	const { selectionSnapshot } = field;

	if (
		selectionSnapshot &&
		selectionSnapshot.anchorNode === selection.anchorNode &&
		selectionSnapshot.anchorOffset === selection.anchorOffset &&
		selectionSnapshot.focusNode === selection.focusNode &&
		selectionSnapshot.focusOffset === selection.focusOffset &&
		selectionSnapshot.processedStart === record.current.start &&
		selectionSnapshot.processedEnd === record.current.end
	) {
		return;
	}

	const { start, end, text } = createRecord();
	const oldRecord = record.current;

	// An empty field has a single caret position, but browsers may
	// resolve a caret after the padding character or on the placeholder
	// element. The caret is then invisible, or the iOS keyboard sees a
	// character before it and does not capitalize. Apply the record's
	// position right away: this runs in the task that placed the caret
	// (see the focus handler), which is what the keyboard requires. It
	// must happen before the snapshot below, so that the selection
	// change event it causes is recognized as processed. Applying again
	// from that later task moves the caret on iOS and the keyboard
	// loses the capital.
	if ( text.length === 0 ) {
		applyRecord( { ...oldRecord, start, end } );
	}

	field.selectionSnapshot = {
		anchorNode: selection.anchorNode,
		anchorOffset: selection.anchorOffset,
		focusNode: selection.focusNode,
		focusOffset: selection.focusOffset,
		processedStart: start,
		processedEnd: end,
	};

	// Fallback mechanism for IE11, which doesn't support the input event.
	// Any input results in a selection change.
	if ( text !== oldRecord.text ) {
		onInput( field );
		return;
	}

	if ( start === oldRecord.start && end === oldRecord.end ) {
		return;
	}

	const newValue = {
		...oldRecord,
		start,
		end,
		// _newActiveFormats may be set on arrow key navigation to control
		// the right boundary position. If undefined, getActiveFormats will
		// give the active formats according to the browser.
		activeFormats: oldRecord._newActiveFormats,
		_newActiveFormats: undefined,
	};

	const newActiveFormats = getActiveFormats( newValue, EMPTY_ACTIVE_FORMATS );

	// Update the value with the new active formats.
	newValue.activeFormats = newActiveFormats;

	// It is important that the internal value is updated first,
	// otherwise the value will be wrong on render!
	record.current = newValue;
	applyRecord( newValue, { domOnly: true } );
	onSelectionChange( start, end );
}

export function onCompositionStart( field: RichTextField ) {
	field.isComposing = true;
	// `handleSelectionChange` returns early while composing, so the
	// selection is not updated as characters are composed (which rerenders
	// the component and might destroy internal browser editing state).
	// Remove the placeholder. Since the rich text value doesn't update
	// during composition, the placeholder doesn't get removed. There's no
	// need to re-add it, when the value is updated on compositionend it
	// will be re-added when the value is empty.
	field.element.querySelector( `[${ PLACEHOLDER_ATTR_NAME }]` )?.remove();
}

export function onCompositionEnd( field: RichTextField ) {
	field.isComposing = false;
	// Ensure the value is up-to-date for browsers that don't emit a final
	// input event after composition.
	onInput( field, { inputType: 'insertText' } );
}

export function onFocus( field: RichTextField, event: FocusEvent ) {
	const { element } = field;
	const { defaultView } = element.ownerDocument;

	// `focusin` bubbles from focusable descendants too — only act
	// when focus lands on the editable itself.
	if ( event.target !== element ) {
		return;
	}

	// `contentEditable` can be false even on a tabindex'd element
	// (e.g. a paragraph with a locked block binding). When that's the
	// case the rich text isn't actually being edited and shouldn't
	// claim selection — block-editor's `use-focus-handler.js` will
	// dispatch `selectionChange(clientId)` to keep `attributeKey`
	// unset for the wrapper-level focus.
	if ( element.contentEditable !== 'true' ) {
		return;
	}

	const { record, isSelected, onSelectionChange, applyRecord } =
		field.props.current;

	// When the whole editor is editable, let writing flow handle
	// selection.
	if ( element.parentElement!.closest( '[contenteditable="true"]' ) ) {
		// A nested editable element does not receive a caret from being
		// focused, unlike an editing host. When the element does not
		// contain the selection, restore the internal record's selection,
		// or match the editing host behavior for programmatic focus and
		// place the caret at the start.
		const selection = defaultView!.getSelection()!;
		if (
			! selection.anchorNode ||
			! element.contains( selection.anchorNode )
		) {
			if ( isSelected && record.current.start !== undefined ) {
				applyRecord( record.current );
			} else {
				selection.collapse( element, 0 );
			}
		}
		return;
	}

	if ( ! isSelected ) {
		// We know for certain that on focus, the old selection is invalid.
		// It will be recalculated on the next mouseup, keyup, or touchend
		// event.
		// `RichTextValue` types `start` and `end` as required for now.
		const index = undefined as unknown as number;

		record.current = {
			...record.current,
			start: index,
			end: index,
			activeFormats: EMPTY_ACTIVE_FORMATS,
		};
		// The record no longer reflects the selection, so a matching
		// snapshot must not skip synchronization.
		field.selectionSnapshot = undefined;
	} else if ( ! field.isPointerDown ) {
		// The document's selection may have moved elsewhere while the
		// element was blurred, so restore it from the record. A pointer
		// press places the caret itself; a selection set during the
		// press would replace it.
		applyRecord( record.current );
	}

	onSelectionChange( record.current.start, record.current.end );

	// There is no selection change event when the element is focused, so
	// we need to manually trigger it. The selection is also not available
	// yet in this call stack.
	window.queueMicrotask( () => handleSelectionChange( field ) );
}
